from __future__ import annotations; import os; import re; import subprocess; from pathlib import Path; ROOT = Path(__file__).resolve().parents[2]; SMOKE = ROOT / 'common/runtime/shell/smoke_test.sh'; DEFAULT_MIN_CHECKS = 12
def _real_check_calls() -> int: text = SMOKE.read_text(encoding='utf-8'); return len(re.findall('^\\s*(?:check_endpoint|wait_for_endpoint)\\s+\\S', text, re.M))
def test_smoke_has_at_least_the_default_minimum_checks() -> None: count = _real_check_calls(); assert count >= DEFAULT_MIN_CHECKS, f'only {count} real smoke checks; add checks or lower MIN_CHECKS'; _m1_result = subprocess.run(['bash', str(SMOKE), 'http://127.0.0.1:1', 'staging'], env={**os.environ, 'MIN_CHECKS': '999', 'SMOKE_READY_ATTEMPTS': '1', 'SMOKE_READY_SLEEP_SECONDS': '0'}, capture_output=True, text=True, timeout=60); assert _m1_result.returncode != 0; assert 'silently-empty' in _m1_result.stdout + _m1_result.stderr
